// assets.js - browser-side asset preloader. Presents the same synchronous interface as the node harness (tools/render.mjs):
//   image(name) -> {w,h,rgb:Uint32Array 0x00RRGGBB}   idx(name) -> {w,h,data,pal}   bin(name) -> Uint8Array   text(name) -> string
// the file list comes from assets/manifest.json (generated by `node tools/mkmanifest.mjs`)

async function decode(blob) {
  const bmp = await createImageBitmap(blob, { colorSpaceConversion: 'none', premultiplyAlpha: 'none' });
  const c = new OffscreenCanvas(bmp.width, bmp.height), g = c.getContext('2d', { willReadFrequently: true });
  g.drawImage(bmp, 0, 0);
  const px = g.getImageData(0, 0, bmp.width, bmp.height).data;
  const rgb = new Uint32Array(bmp.width * bmp.height);
  for (let i = 0, j = 0; i < rgb.length; i++, j += 4) rgb[i] = (px[j] << 16) | (px[j + 1] << 8) | px[j + 2];
  return { w: bmp.width, h: bmp.height, rgb };
}

export async function loadAssets(base, onProgress) {
  const files = await (await fetch(base + 'manifest.json')).json();
  const imgs = {}, bins = {}, texts = {};
  let done = 0; const tick = () => onProgress && onProgress(++done / files.length);
  const get = (n) => fetch(base + n).then((r) => { if (!r.ok) throw new Error(n + ' ' + r.status); return r; });
  await Promise.all(files.map((n) => {
    if (/\.(png|jpg)$/.test(n)) return get(n).then((r) => r.blob()).then(decode).then((im) => { imgs[n] = im; tick(); });
    if (n === 'script.unr') return get(n).then((r) => r.text()).then((t) => { texts[n] = t; tick(); });
    if (n === 'tour2.xm') { tick(); return null; } // streamed by the audio player
    return get(n).then((r) => r.arrayBuffer()).then((b) => { bins[n] = new Uint8Array(b); tick(); });
  }));
  const norm = (n) => n.toLowerCase().replace(/\.tga$/, '.png').replace(/\.unr$/, '.png');
  return {
    text: (n) => { n = n.toLowerCase(); return texts[n] ?? new TextDecoder('latin1').decode(bins[n]); },
    bin: (n) => bins[n.toLowerCase()],
    image(n) { const k = norm(n); if (!imgs[k]) throw new Error('no image ' + n); return imgs[k]; },
    idx(n) { const b = n.toLowerCase().replace(/\.tga$/, ''); return { w: 256, h: 256, data: bins[b + '.idx'], pal: bins[b + '.tgapal'] || null }; },
  };
}
